// BAD: Improper use of Java API (vulnerable)
// Example: Using string concatenation to build SQL query and unsafely creating XML parser
import java.sql.*;
import javax.xml.parsers.*;
import org.w3c.dom.Document;
import java.io.StringReader;
import javax.xml.parsers.ParserConfigurationException;
import org.xml.sax.InputSource;

public class InsecureExample {
    // Simulated user input
    static String userInputUsername = "admin";
    static String userInputPassword = "' OR '1'='1"; // classic SQL injection payload

    // Simulated untrusted XML input (external entity attack)
    static String userProvidedXml = "<?xml version=\"1.0\"?>\n" +
            "<!DOCTYPE foo [ <!ENTITY xxe SYSTEM \"file:///etc/passwd\"> ]>\n" +
            "<creds><user>alice</user><secret>&xxe;</secret></creds>";

    public static void main(String[] args) throws Exception {
        // BAD: vulnerable - building SQL with concatenation enables SQL injection
        try (Connection conn = DriverManager.getConnection("jdbc:yourdb://host/db", "u", "p");
             Statement stmt = conn.createStatement()) {
            String sql = "SELECT * FROM users WHERE username = '" + userInputUsername +
                         "' AND password = '" + userInputPassword + "'"; // vulnerable
            ResultSet rs = stmt.executeQuery(sql);
            while (rs.next()) {
                System.out.println("Welcome " + rs.getString("username"));
            }
        }

        // BAD: vulnerable - unsafe XML parser with XXE enabled by default in some configurations
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // missing secure settings, allows external entities (XXE) - vulnerable
        DocumentBuilder builder = dbf.newDocumentBuilder();
        Document doc = builder.parse(new InputSource(new StringReader(userProvidedXml)));
        System.out.println("Parsed secret: " + doc.getElementsByTagName("secret").item(0).getTextContent());
    }
}
***
/*
GOOD: Secure use of Java APIs
- Use PreparedStatement with bind parameters to prevent SQL injection
- Harden XML parser to disable external entities and DTDs (prevent XXE)
*/
import java.sql.*;
import javax.xml.parsers.*;
import org.w3c.dom.Document;
import java.io.StringReader;
import org.xml.sax.InputSource;

public class SecureExample {
    static String userInputUsername = "admin";
    static String userInputPassword = "' OR '1'='1"; // harmless when bound as data

    static String userProvidedXml = "<?xml version=\"1.0\"?><creds><user>alice</user><secret>none</secret></creds>";

    public static void main(String[] args) throws Exception {
        // GOOD: Use PreparedStatement and parameter binding
        try (Connection conn = DriverManager.getConnection("jdbc:yourdb://host/db", "u", "p");
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT * FROM users WHERE username = ? AND password = ?")) {
            ps.setString(1, userInputUsername);
            ps.setString(2, userInputPassword);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    System.out.println("Welcome " + rs.getString("username"));
                }
            }
        }

        // GOOD: Secure XML parsing configuration to prevent XXE
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Disable DTDs entirely
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // If the above isn't supported by the parser, also ensure external entities are disabled
        try {
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        } catch (ParserConfigurationException ignored) { }
        try {
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (ParserConfigurationException ignored) { }

        // Disable XInclude and expansion of entity references
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);

        // Recommended: secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        DocumentBuilder builder = dbf.newDocumentBuilder();
        Document doc = builder.parse(new InputSource(new StringReader(userProvidedXml)));
        System.out.println("Parsed secret (safe): " + doc.getElementsByTagName("secret").item(0).getTextContent());
    }
}

