// Poor (vulnerable) example: Using Runtime.exec with unsanitized user input (Command Injection)
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class InsecureCommandServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        // User-controlled input (e.g., "ls; rm -rf /") — vulnerable
        String userArg = request.getParameter("arg");

        // Improper API use: passing raw input into Runtime.exec can lead to command injection
        String cmd = "ping -c 1 " + userArg;

        Process p = Runtime.getRuntime().exec(cmd); // Dangerous: concatenated command
        BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));
        String line;
        StringBuilder out = new StringBuilder();
        while ((line = br.readLine()) != null) {
            out.append(line).append("\n");
        }

        response.setContentType("text/plain");
        response.getWriter().write(out.toString());
    }
}
***
/*
Sound example: Avoid shell execution. Validate input and use safe APIs.
If shelling out is absolutely required, use ProcessBuilder with fixed command and strict whitelisting.
*/
import java.io.*;
import java.util.regex.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class SecureCommandServlet extends HttpServlet {

    // Strict regex for IPv4 (example of input you expect). Adjust as appropriate.
    private static final Pattern IPV4 =
        Pattern.compile("^((25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)(\\.|$)){4}$");

    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userArg = request.getParameter("arg");

        // Validate and canonicalize input
        if (userArg == null || !IPV4.matcher(userArg.trim()).matches()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.setContentType("text/plain");
            response.getWriter().write("Invalid input");
            return;
        }
        String ip = userArg.trim();

        // Prefer safe Java APIs: here we emulate a ping by opening a socket instead of shelling out.
        // This avoids invoking the shell entirely.
        boolean reachable = false;
        try {
            reachable = java.net.InetAddress.getByName(ip).isReachable(2000);
        } catch (IOException e) {
            // Log appropriately in real code; avoid leaking details to the client
            reachable = false;
        }

        response.setContentType("text/plain");
        response.getWriter().write("Reachable: " + reachable);

        // If you must call external commands, use ProcessBuilder with fixed arguments
        // and do NOT concatenate user input into a single command string.
        // Example (commented out):
        /*
        ProcessBuilder pb = new ProcessBuilder("ping", "-c", "1", ip); // ip is validated above
        pb.redirectErrorStream(true);
        Process p = pb.start(); // Safer than Runtime.exec with concatenation
        try (BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
            String line;
            StringBuilder out = new StringBuilder();
            while ((line = br.readLine()) != null) {
                out.append(line).append("\n");
            }
            response.getWriter().write(out.toString());
        }
        */
    }
}

